private typealias E = EvidenceSeed

/// Follow-up trials, batch BH: the same defendant comes back to this court.
extension FollowUpCases {
    static let batchBH: [CaseTemplate] = [scaldChildAbuseAgain2, privateImagesPostAgain2, clubAmbushKillingAgain2, constructionDumpingAgain2, payrollClerkTheftAgain2, prankNineOneOneAgain2, painClinicAgain2, homeInvasionAgain2, formerRoommateKeyAgain2, formerEmployeeFilesAgain2, heatOfPassionAgain2, loyaltyCardClonesAgain2, jailLockdownRiotAgain2, lakeCrashFatalAgain2, pillPressAgain2]

    static let scaldChildAbuseAgain2 = SmallCases.make(
        key: "story.followup.scaldChildAbuseAgain2",
        category: .family,
        headlines: ["Parent Again Charged After Child Found Alone in Parking Lot at 2 A.M."],
        law: "childAbuseMisd",
        threshold: 6,
        spec: "Being the parent of {V}, a child, created a substantial risk of physical injury to {V.him} other than by accidental means, by leaving {V.him} unsupervised overnight, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a neighbor found {V}, a six-year-old, barefoot in an apartment lot at 2 a.m. while {D} worked a night shift across town. {DL} says a sitter was supposed to be there.",
        state: [E(.statement, 3, "Neighbor", "Found {V} crying in the lot at 2 a.m."), E(.document, 3, "Timeclock", "{D} clocked in across town at 10:30 p.m.")],
        defense: [E(.digital, 1, "Sitter Text", "{DL} says a sitter was supposed to come.")],
        role: "Neighbor",
        exam: [.direct("What did you find that night?", "\"I came home from my own late shift and saw a small child walking barefoot across the apartment parking lot, crying.\""), .direct("What time was it?", "\"About two in the morning, and it was cold, with the ground wet and frost starting to form.\""), .direct("What did you do?", "\"I put my coat around {V}, took {V.him} to my apartment, and called the sheriff's office.\""), .direct("What did {V} tell you?", "\"That {V.he} woke up alone, couldn't find anyone, and went outside to look for a parent.\""), .direct("How old was {V}?", "\"Six years old, and very scared. {V.He} was shivering, and {V.his} feet were red from the cold.\""), .direct("What did the timeclock show about {DL}?", "\"That {D.he} clocked in at a job across town at ten-thirty that night, and wasn't home.\""), .cross("You didn't see {DL} at the apartment?", "\"No, {D.he} wasn't there when I found the child.\""), .cross("{V} wasn't hurt?", "\"Only cold and frightened, with scrapes on {V.his} feet.\""), .cross("{DL} came home later?", "\"Yes, about an hour after the deputy arrived, and {D.he} was upset.\""), .cross("{DL} said a sitter was coming?", "\"Yes, {D.he} told the deputy that a sitter was supposed to be there that night.\""), .cross("You've lived near {DL} for a while?", "\"About a year, and I've seen {V} with {D.him} often.\"")],
        theory: ("{D} left a child alone overnight.", "A sitter who never came."),
        allocution: "\"My sitter backed out that night and I could not miss work. I called twice and nobody picked up. I thought {V} was asleep. I should have stayed home. I know I was in this court before, and I'm sorry for the fear {V} must have felt in that parking lot.\"",
        truths: ("{DL} never arranged any sitter that night.", "A sitter's text shows she canceled at the last minute."),
        defendant: [.direct("Did you leave your child alone?", "\"I left my child with a sitter who was supposed to come. She didn't come, and I didn't know.\""), .direct("Who was the sitter?", "\"A neighbor I've used before. She texted me that she'd be there by ten, and then she didn't show.\""), .direct("Why didn't you check?", "\"I was already at work, and I couldn't leave my shift. I trusted her text.\""), .direct("Why didn't you call home?", "\"I did call, but my child was asleep and didn't pick up. I thought that meant everything was fine.\""), .direct("What did you do when you learned?", "\"I rushed home. I held my child and cried. I felt terrible.\""), .direct("What would you tell your child and the neighbor?", "\"I'm so sorry I wasn't there. Thank you for finding my child and keeping {V.him} safe.\""), .cross("You've been investigated for leaving a child alone before, haven't you?", "\"Yes, and I told the court I'd never do it again. I trusted the wrong person.\""), .cross("You went to work knowing no adult was in the home?", "\"I thought a sitter was coming, but I didn't confirm.\""), .cross("A six-year-old alone overnight is a serious risk?", "\"It is a serious risk for a young child, and I know that very well.\""), .cross("You'll arrange proper child care?", "\"Yes, I'll arrange proper child care with family members I can trust before I work.\""), .cross("You'll accept parenting classes?", "\"Yes, I'll accept parenting classes and any supervision the court thinks is needed.\"")],
        openings: ("A neighbor who came home from a late shift saw {V}, a six-year-old, walking barefoot across the apartment lot at about two in the morning, crying, in the cold with frost forming, while {D} worked a night shift across town, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say a sitter was supposed to be at the apartment that night and never came, and {D} did not know {V} was alone. {D} was at work across town."),
        closings: ("A six-year-old was alone outside at two in the morning in the cold, {D} was across town, and after {PRIOR} {DL} understood exactly what leaving a child with no sitter means.", "A sitter who never came is not {D}'s decision to leave a child alone. The State must prove {D} knew {V} was alone when {D.he} went to work."),
        timeline: [(0, "10:30 p.m.: {DL} clocks in."), (0, "2 a.m.: the neighbor finds {V}."), (0, "2:20 a.m.: deputies arrive.")],
        identified: "A neighbor's report.",
        aggravating: ["The victim was a young child"],
        mood: .divided)

    static let privateImagesPostAgain2 = SmallCases.make(
        key: "story.followup.privateImagesPostAgain2",
        category: .cyber,
        headlines: ["Ex-Partner Posts Private Photos to a 40-Member Team Chat"],
        law: "privateImages",
        threshold: 5,
        spec: "Knowingly disclosed private intimate images of {V} without consent, with intent to cause harm, on {DATE}.",
        ages: 23...35,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, private photos of {V} appeared in a 40-member recreational-league group chat at 9:05 p.m., sent from {D}'s account. The post was deleted two minutes later. {DL} says a friend was holding {D.his} phone.",
        state: [E(.digital, 3, "Chat Log", "{D}'s account posts six photos at 9:05 p.m. and deletes them at 9:07."), E(.digital, 2, "Moderator Screenshot", "A moderator's screenshot of the photos.")],
        defense: [E(.statement, 1, "Phone Handed Over", "{DL} says a friend was using {D.his} phone.")],
        role: "League moderator",
        exam: [.direct("What is your role?", "\"I'm a moderator for a recreational-league group chat, with about forty members who play together.\""), .direct("What happened at 9:05 p.m.?", "\"Six private photos of {V} appeared in the group chat, posted from {DL}'s account, with no warning or caption.\""), .direct("How did you react?", "\"I took a screenshot of the photos and then deleted them two minutes later, when I saw how shocking they were.\""), .direct("What does the chat log show?", "\"{DL}'s account posting six photos at 9:05 and removing them at 9:07, with several members already having seen them.\""), .direct("What did {V} say?", "\"That the photos were private and had been shared only with {DL} in a relationship that had ended.\""), .direct("What did {DL} say?", "\"{D.He} said a friend was using {D.his} phone and sent them without permission.\""), .cross("The photos were posted from {DL}'s account?", "\"Yes, the chat log shows that the photos were posted from {DL}'s account.\""), .cross("You can't say who held the phone?", "\"No, I can only say that it was {DL}'s account, not who held the phone.\""), .cross("The photos were deleted quickly?", "\"Yes, they were deleted within two minutes, but many members had already seen them.\""), .cross("{DL} was in the group chat?", "\"Yes, {D.he} was a member of the group for about a year before this.\""), .cross("{V} was devastated?", "\"Yes, {V.he} was devastated, and {V.he} left the league after that night.\"")],
        theory: ("{D} posted private photos to hurt {V.him}.", "A friend with {D.his} phone."),
        allocution: "\"Those photos were with a friend at a party, and I forgot they were still on my phone. I never meant to send them to anyone. I was angry, and I should never have kept them.\"",
        truths: ("{DL} still had the photos in a hidden folder after the first case.", "A friend with {DL}'s phone passcode admitted posting them as a joke."),
        defendant: [.direct("Did you post the photos?", "\"No. A friend was using my phone, and he posted them without my permission.\""), .direct("Who is the friend?", "\"A man who borrowed my phone at the league event. I'll give his name to the court.\""), .direct("Why did he have your phone?", "\"He asked to use it to call his ride, and I handed it over. I didn't think about the photos.\""), .direct("Why were the photos on your phone?", "\"They were from when we dated. I should have deleted them, and I didn't.\""), .direct("What did you do when you found out?", "\"I took my phone back, deleted the posts, and called {V.him} to apologize.\""), .direct("What would you tell {V}?", "\"I'm so sorry that your photos were shared. I should have deleted them, and I'll never forgive myself.\""), .cross("You've been charged with sharing private images before, haven't you?", "\"Yes, and I promised the court that I would never do this again. I kept the photos anyway.\""), .cross("You kept private photos after the relationship ended?", "\"I did keep the photos after we broke up, and that was wrong.\""), .cross("You handed your unlocked phone to someone else?", "\"I did hand my phone to someone else, unlocked, and I should have known better.\""), .cross("You'll give the court the friend's name?", "\"Yes, I'll give the court the friend's name and his number, today.\""), .cross("You'll stay away from {V}?", "\"Yes, entirely. I won't contact {V.him}, or go near {V.his} home or workplace.\"")],
        openings: ("A moderator of a recreational-league group chat with about forty members saw six private photos of {V} appear in the chat at 9:05 p.m., posted from {D}'s account with no warning or caption, and the post was deleted two minutes later, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend was holding {D}'s phone at the time and posted the photos, and {D} did not post anything. The account is {D}'s, but the hand was not."),
        closings: ("The photos went up from {D}'s account at 9:05 p.m. and came down two minutes later, and with {PRIOR} behind {D.him}, {DL} knew what those photos were and who had them.", "A phone in a friend's hand posts under its owner's name. The State must prove {D} posted the photos and meant to hurt {V}."),
        timeline: [(0, "9:05 p.m.: the photos are posted."), (0, "9:07 p.m.: they are deleted."), (1, "{V} reports to police.")],
        identified: "A chat log.",
        aggravating: ["The images were sent to many people"],
        mood: .wantsConviction)

    static let clubAmbushKillingAgain2 = SmallCases.make(
        key: "story.followup.clubAmbushKillingAgain2",
        category: .violent,
        headlines: ["Shotgun Pointed at Biker Club Member at Fuel Pump"],
        law: "assaultPointingGun",
        spec: "Assaulted {V} by pointing a gun at {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a gas station camera on {DATE} showed {D} pulling a shotgun from a truck rack and pointing it at {V}, a club member, at the next pump. {DL} says the gun never left the rack.",
        state: [E(.video, 3, "Pump Camera", "{D} aims a shotgun at {V} for about five seconds."), E(.physical, 2, "Shotgun", "A loaded shotgun recovered from {D}'s truck.", .search)],
        defense: [E(.statement, 1, "Rack Only", "{DL} says the gun stayed in the rack.")],
        role: "Gas station clerk",
        exam: [.direct("What is your job?", "\"I'm a clerk at a gas station, and I work the counter and watch the pumps from a window.\""), .direct("What did you see?", "\"A man pulled a shotgun out of the rack in his truck and pointed it at another man at the next pump.\""), .direct("How long did it last?", "\"About five seconds, which felt much longer, with the barrel aimed right at the other man's chest.\""), .direct("What does the pump camera show?", "\"{DL} taking the shotgun from the rack, aiming it at {V}, and then lowering it and driving away.\""), .direct("What did you do?", "\"I called 911 immediately and gave them the truck's plate and a description.\""), .direct("What was found in {DL}'s truck?", "\"A loaded shotgun in the rack, with the safety off, according to the deputy.\""), .cross("{DL} didn't fire?", "\"No, {D.he} didn't fire. {D.He} lowered the gun and drove away from the pumps.\""), .cross("{V} and {DL} were arguing before?", "\"Yes, they were shouting at each other across the pumps.\""), .cross("{V} was frightened?", "\"Very frightened. {V.He} dropped to the ground and covered {V.his} head.\""), .cross("You couldn't hear what they said?", "\"Not clearly, since I was behind the window and the pumps were noisy.\""), .cross("{DL} says the gun never left the rack?", "\"That's what {D.he} says, but the camera shows otherwise.\"")],
        theory: ("{D} aimed a shotgun at a rival.", "A gun that stayed in a rack."),
        allocution: "\"The gun never left the rack. I'd been shooting at a range that day, and I was reaching for the rack when we argued. I lost my temper at that pump. I know I was in this court before, and I'm sorry to {V} and to the people at the station.\"",
        truths: ("{DL} texted a friend that morning, 'I'll end it at the pump.'", "{V} reached into a vest first, the camera shows."),
        defendant: [.direct("Did you point a shotgun at {V}?", "\"No. The gun never left the rack. I put my hand near it, but I didn't take it out.\""), .direct("What was the argument about?", "\"{V.He} cut me off in the lot, and we shouted. I was angry, and I reached toward the rack.\""), .direct("Why did you reach toward the gun?", "\"I was rattled, and I wanted to feel safe. I didn't plan to aim it.\""), .direct("What does the video show?", "\"It's hard to see, and it may look like I held the gun. I know how it looks.\""), .direct("What did you do after?", "\"I got into my truck and drove away. I was shaken.\""), .direct("What would you tell {V}?", "\"I'm sorry for scaring you. I'll stay away from you and keep my gun locked up.\""), .cross("You've been charged with pointing a gun at someone before, haven't you?", "\"Yes, and I gave the court my word that it wouldn't happen a second time. I'm ashamed.\""), .cross("The safety was off on a loaded shotgun in your rack?", "\"It was loaded with the safety off, and that was careless of me.\""), .cross("The camera shows you aiming for five seconds?", "\"It looks that way, and I can't dispute it.\""), .cross("You'll give up your guns?", "\"Yes, I'll give up all of my guns today, and the court can hold them.\""), .cross("You'll avoid {V}?", "\"Yes, I'll avoid {V.him} and stay away from that gas station entirely.\"")],
        openings: ("A gas station clerk who watches the pumps from the counter saw a man pull a shotgun out of the rack in his truck and point it at another man at the next pump, and the gas station camera shows {D} pointing it at {V}, a club member, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the gun never left the rack, and {D} only reached toward it. A man who touches a gun on a rack has not pointed it at anyone."),
        closings: ("The camera shows {D} pulling a shotgun from the rack and pointing it at {V}, and after {PRIOR} {DL} knew exactly what pointing a shotgun at a rival means.", "A gun that stayed in the rack was never aimed. The State must prove {D} pointed the shotgun at {V} and did not merely reach."),
        timeline: [(0, "4:10 p.m.: both trucks stop at the pumps."), (0, "4:12 p.m.: the shotgun is raised."), (0, "4:20 p.m.: deputies arrive.")],
        identified: "A gas station camera.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction)

    static let constructionDumpingAgain2 = SmallCases.make(
        key: "story.followup.constructionDumpingAgain2",
        category: .property,
        headlines: ["Roofing Crew Loads Shingles at Supply Yard Without Paying"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole forty bundles of roofing shingles valued at $1,900 from {V}, a supply yard, on {DATE}.",
        ages: 25...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a yard camera showed a truck lettered with {D}'s roofing company loading forty bundles of shingles at 5:50 a.m. on {DATE}. The account had been suspended. {DL} says a yard worker waved the truck in.",
        state: [E(.video, 3, "Yard Camera", "{D}'s company truck loads forty bundles."), E(.document, 3, "Account Hold", "The account was suspended two weeks earlier for non-payment.")],
        defense: [E(.statement, 1, "Waved In", "{DL} says a yard worker waved the truck in.")],
        role: "Yard manager",
        exam: [.direct("What is your position?", "\"I'm the manager of a roofing supply yard, where contractors buy shingles, nails, and other materials.\""), .direct("What happened that morning?", "\"At about ten to six, before we opened, a truck lettered with {DL}'s roofing company loaded forty bundles of shingles.\""), .direct("What does the yard camera show?", "\"The company truck backing up to a stack, men loading forty bundles, and the truck leaving without anyone stopping at the office.\""), .direct("What was the value?", "\"About nineteen hundred dollars worth of shingles, which is a day's sales for a small yard.\""), .direct("What was the status of {DL}'s account?", "\"It had been suspended two weeks earlier for non-payment, and {DL} had been told no more credit.\""), .direct("What did {DL} say?", "\"{D.He} said a yard worker waved the truck in and that {D.he} thought the load was on credit.\""), .cross("A yard worker was on site?", "\"One worker was there early, but he says he didn't wave anyone in.\""), .cross("{DL} has been a customer for years?", "\"Yes, {D.he} has been a customer for years, and I liked doing business with {D.him}.\""), .cross("{DL} didn't try to hide?", "\"The truck carried the company name in plain sight.\""), .cross("{DL} paid for the shingles later?", "\"No, {D.he} hasn't paid for the shingles yet, and the account is still past due.\""), .cross("The gate was open?", "\"Yes, we open the gate before the office opens.\"")],
        theory: ("{D} took shingles from a yard on a suspended account.", "A yard worker waved the truck in."),
        allocution: "\"I'm not sure that was my truck loading shingles. The yard opens early and my company's name is on many trucks. I'm sorry for the loss to the yard, and I'll pay for it.\"",
        truths: ("{DL} was told by phone the account was suspended.", "The yard worker wrote the load in a notebook and never entered it."),
        defendant: [.direct("Did you take the shingles?", "\"I loaded them, but a yard worker waved us in. I thought it was fine, since I've bought there for years.\""), .direct("Did you know your account was suspended?", "\"I knew I was behind, but I thought I could arrange to pay. I didn't think they'd cut me off.\""), .direct("Why did you go before the office opened?", "\"I had a job that morning and needed the materials early. I'd done it before.\""), .direct("Why didn't you stop at the office?", "\"The worker waved us on, and I assumed he'd log the load.\""), .direct("What did you do when the manager called?", "\"I said I would pay, and I offered to return the shingles if needed.\""), .direct("What would you tell the manager?", "\"I'm sorry for the misunderstanding. I'll pay for the shingles in full.\""), .cross("You've been told not to load without paying before, haven't you?", "\"Yes, and I should have gone to the office. I didn't.\""), .cross("You knew your account was behind?", "\"I did know the account was behind, and I should have called before I went.\""), .cross("A wave from a worker doesn't authorize credit, does it?", "\"A wave doesn't authorize credit, and I see that now that I think about it.\""), .cross("You'll pay nineteen hundred dollars?", "\"Yes, I'll pay the nineteen hundred dollars today, from my savings.\""), .cross("You'll buy with cash from now on?", "\"Yes, I'll pay cash for every purchase from now on, and I'll go to the office first.\"")],
        openings: ("The manager of a roofing supply yard where contractors buy shingles and nails watched a yard camera show a truck lettered with {D}'s roofing company load forty bundles of shingles at about ten to six in the morning, before opening, on an account that had been suspended, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say a yard worker waved the truck in, and {D} believed the account was in good standing. {D} loaded what {D.he} was allowed to load."),
        closings: ("The account was suspended, the camera shows the truck loading forty bundles before the yard opened, and with {PRIOR} already on {D.his} record, {DL} knew exactly what a suspended account means.", "A yard worker who waves a truck in invites it. The State must prove {D} knew the account was suspended when {D.he} took the shingles."),
        timeline: [(-14, "The account is suspended."), (0, "5:50 a.m.: the truck loads."), (0, "8 a.m.: the yard counts bundles.")],
        identified: "A yard camera.",
        mood: .indifferent)

    static let payrollClerkTheftAgain2 = SmallCases.make(
        key: "story.followup.payrollClerkTheftAgain2",
        category: .whiteCollar,
        headlines: ["Co-op Bookkeeper Sent Customer Refunds to a Prepaid Card"],
        law: "embezzlement",
        threshold: 6,
        spec: "Embezzled $23,000 entrusted to {D} by {V}, a farm co-op, on {DATE}.",
        ages: 30...62,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a farm co-op found $23,000 in customer refunds paid to a prepaid card over eight months. {D}, the bookkeeper, entered every refund. {DL} says the manager approved a new refund process.",
        state: [E(.digital, 3, "Refund Log", "Eight months of refunds to one prepaid card, entered by {D}."), E(.document, 3, "Card Statement", "The card is registered to a mailbox {D} rents.")],
        defense: [E(.statement, 1, "New Process", "{DL} says the manager approved the refund process.")],
        role: "Co-op manager",
        exam: [.direct("What is your position?", "\"I'm the manager of a farm co-op, which sells supplies to local farmers and returns money to members.\""), .direct("What did you discover?", "\"That twenty-three thousand dollars in customer refunds had been paid to a single prepaid card over eight months.\""), .direct("Who entered the refunds?", "\"{DL}, our bookkeeper, who handled refunds and payments and had access to the accounting system.\""), .direct("What does the refund log show?", "\"Eight months of refunds, each to the same card, entered by {DL}, with no matching customers or returns.\""), .direct("Who owns the card?", "\"The card statement shows it's registered to a mailbox that {DL} rents under {D.his} own name.\""), .direct("What did {DL} say?", "\"{D.He} said I approved a new refund process, and that {D.he} followed it.\""), .cross("You never approved such a process?", "\"No. I would never approve refunds to one card.\""), .cross("{DL} has been the bookkeeper for years?", "\"Yes, {D.he} has been the bookkeeper for six years, and I trusted {D.him} completely.\""), .cross("The refunds were small?", "\"Yes, a few hundred dollars each, but they added up.\""), .cross("No customers complained?", "\"No, no customers complained, because the refunds were fake and went to one card.\""), .cross("{DL} hasn't returned the money?", "\"No, {D.he} hasn't returned any of the money, and {D.he} hasn't offered to.\"")],
        theory: ("{D} sent customer refunds to a personal card.", "A manager-approved process."),
        allocution: "\"The manager gave me a vendor card to use, and I used it only for the co-op's business and for my mail. I know I was in this court before, and I understand the doubt. I'm sorry for the refunds that went missing, and I'll cooperate with every audit.\"",
        truths: ("The customers named in the refunds never asked for any.", "The manager's initials approved a similar batch earlier."),
        defendant: [.direct("Did you take the refunds?", "\"I processed the refunds, but I didn't take the money for myself. I thought it was a new process.\""), .direct("Who told you about the new process?", "\"The manager said we'd handle refunds differently. I thought she meant to a single card.\""), .direct("Why did you rent the mailbox?", "\"I rent it for personal mail. I didn't think about it when I entered the card.\""), .direct("Did you know the refunds were fake?", "\"I didn't think they were. I thought they were returns.\""), .direct("What did you do when the manager questioned you?", "\"I told her what I did and showed her the log.\""), .direct("What would you tell the manager and the members?", "\"I'm sorry for the loss. I never meant to hurt the co-op, and I'll cooperate.\""), .cross("You've been convicted of embezzlement before, haven't you?", "\"Yes, and I swore I'd never do it again. I'm ashamed.\""), .cross("Twenty-three thousand dollars went to a card tied to your mailbox?", "\"It did go to a card tied to my mailbox, and I know how that looks.\""), .cross("You entered every refund yourself?", "\"I did, and I should have asked for a second approval.\""), .cross("You'll repay the co-op?", "\"Yes, I'll repay the co-op on a plan that the court and the members approve.\""), .cross("You'll never handle money again?", "\"Never again. I'll never hold a job where I handle money for other people.\"")],
        openings: ("The manager of a farm co-op that sells supplies to local farmers and returns money to members found that $23,000 in customer refunds had been paid to a single prepaid card over eight months, and {D}, the bookkeeper, entered every refund, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the manager approved a new refund process, and {D} followed it as instructed. {D} did not choose the card."),
        closings: ("The refunds went to one prepaid card for eight months, {D} entered every one, and having faced {PRIOR} before, {DL} understood exactly where refunds are meant to go.", "A process approved by the manager is the manager's, and {D} entered what was told. The State must prove {D} knew the card was not the customers'."),
        timeline: [(-240, "The first refund."), (-30, "A customer questions a charge."), (0, "The audit begins.")],
        identified: "A refund log.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

